import 'package:flutter/material.dart';

class ZambianLanguage {
  final String code;
  final String name;
  final String nativeName;
  final String flagEmoji;
  final Color color;
  final String region;
  final String description;
  final List<ZambianUnit> units;

  const ZambianLanguage({
    required this.code,
    required this.name,
    required this.nativeName,
    required this.flagEmoji,
    required this.color,
    required this.region,
    required this.description,
    required this.units,
  });
}

class ZambianUnit {
  final String id;
  final String title;
  final String subtitle;
  final String emoji;
  final String imageUrl;
  final List<ZambianLesson> lessons;
  final bool isUnlocked;

  const ZambianUnit({
    required this.id,
    required this.title,
    required this.subtitle,
    required this.emoji,
    required this.imageUrl,
    required this.lessons,
    this.isUnlocked = false,
  });
}

class ZambianLesson {
  final String id;
  final String title;
  final String description;
  final int xpReward;
  final bool isSlang;
  final bool isCompleted;
  final bool isUnlocked;
  final List<ZambianExercise> exercises;

  const ZambianLesson({
    required this.id,
    required this.title,
    required this.description,
    required this.xpReward,
    this.isSlang = false,
    this.isCompleted = false,
    this.isUnlocked = false,
    required this.exercises,
  });
}

class ZambianExercise {
  final String
  type; // multiple_choice, complete_the_chat, tap_the_word, listen_and_pick, match_activity
  final String instruction;
  final String question;
  final String correctAnswer;
  final List<String> options;
  final String? culturalNote;
  final String? audioText;
  final String? mascotMessage;
  final List<String>? wordBank;
  final int xpReward;

  const ZambianExercise({
    required this.type,
    required this.instruction,
    required this.question,
    required this.correctAnswer,
    required this.options,
    this.culturalNote,
    this.audioText,
    this.mascotMessage,
    this.wordBank,
    this.xpReward = 10,
  });
}

