  static ZambianLanguage? getLanguage(String code) {
    try {
      return languages.firstWhere((l) => l.code == code);
    } catch (_) {
      return null;
    }
  }

  // Per-language progress keys for SharedPreferences
  static String progressKey(String languageCode, String lessonId) =>
      'progress_${languageCode}_$lessonId';

  static String lastLessonKey(String languageCode) =>
      'last_lesson_$languageCode';

  static List<ZambianUnit> getUnitsForLanguage(String code) {
    switch (code) {
      case 'bemba':
        return [..._bembaUnits, ..._bembaExtraUnits];
      case 'nyanja':
        return [..._nyanjaUnits, ..._nyanjaExtraUnits];
      case 'tonga':
        return [..._tongaUnits, ..._tongaExtraUnits];
      case 'lozi':
        return [..._loziUnits, ..._loziExtraUnits];
      case 'lunda':
        return [..._lundaUnits, ..._lundaExtraUnits];
      case 'kaonde':
        return [..._kaondeUnits, ..._kaondeExtraUnits];
      case 'luvale':
        return [..._luvaleUnits, ..._luvaleExtraUnits];
      default:
        return [];
    }
  }

